/**
 * fix-react-conflicts.js
 *
 * Reads and validates all workspace package.json files, detects React
 * peer-dependency conflicts (mismatched major versions of react / react-dom),
 * resolves them by aligning to the highest compatible React version, and
 * verifies with `npm install`.
 *
 * Exit codes:
 *   0 - success (conflicts resolved, or no conflicts and no changes made)
 *   1 - failure (missing file, invalid JSON, unresolvable conflict, or
 *       post-fix `npm install` failure)
 *
 * Failure paths never modify any package.json file: all validation and
 * resolution decisions happen in memory first; files are written only when a
 * complete, resolvable fix has been computed.
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const ROOT = process.cwd();
const ROOT_PKG = path.join(ROOT, 'package.json');

const REACT_KEYS = ['react', 'react-dom'];
const TYPES_KEYS = ['@types/react', '@types/react-dom'];
const DEP_SECTIONS = ['dependencies', 'devDependencies', 'peerDependencies', 'optionalDependencies'];

function fail(message) {
  console.error(`Error: ${message}`);
  process.exit(1);
}

function ok(message) {
  console.log(message);
}

/** Expand simple workspace globs (supports `*`) into package.json paths. */
function discoverWorkspaceFiles(rootPkg) {
  const patterns = rootPkg.workspaces;
  let globs = [];
  if (Array.isArray(patterns)) globs = patterns;
  else if (patterns && Array.isArray(patterns.packages)) globs = patterns.packages;
  else {
    // No workspaces field: fall back to conventional layout.
    globs = ['packages/*'];
  }
  const files = [ROOT_PKG];
  for (const pattern of globs) {
    if (typeof pattern !== 'string') continue;
    if (!pattern.includes('*')) {
      files.push(path.join(ROOT, pattern, 'package.json'));
    } else {
      const prefix = pattern.split('*')[0];
      const baseDir = path.join(ROOT, prefix);
      let entries = [];
      try {
        entries = fs.readdirSync(baseDir, { withFileTypes: true });
      } catch (e) {
        fail(`cannot read workspace directory "${baseDir}": ${e.message}`);
      }
      for (const entry of entries) {
        if (entry.isDirectory()) {
          files.push(path.join(baseDir, entry.name, 'package.json'));
        }
      }
    }
  }
  // De-duplicate while preserving order.
  return [...new Set(files)];
}

/** Extract the first X.Y.Z triple from an npm version spec. Returns null if none. */
function parseBaseVersion(spec) {
  if (typeof spec !== 'string') return null;
  const m = spec.match(/(\d+)\.(\d+)\.(\d+)/);
  if (!m) return null;
  return { major: Number(m[1]), minor: Number(m[2]), patch: Number(m[3]), base: `${m[1]}.${m[2]}.${m[3]}` };
}

function compareVersions(a, b) {
  if (a.major !== b.major) return a.major - b.major;
  if (a.minor !== b.minor) return a.minor - b.minor;
  return a.patch - b.patch;
}

function main() {
  // ---- Phase 1: validate root package.json exists and parses ----
  if (!fs.existsSync(ROOT_PKG)) {
    fail(`package.json is missing: ${ROOT_PKG}`);
  }
  let rootPkg;
  try {
    rootPkg = JSON.parse(fs.readFileSync(ROOT_PKG, 'utf8'));
  } catch (e) {
    fail(`package.json contains invalid JSON (${ROOT_PKG}): ${e.message}`);
  }

  // ---- Phase 2: discover + validate every workspace package.json ----
  const files = discoverWorkspaceFiles(rootPkg);

  // The root file is already validated; validate the rest exist + parse.
  const parsed = new Map(); // file -> object
  parsed.set(ROOT_PKG, rootPkg);

  for (const file of files) {
    if (parsed.has(file)) continue;
    if (!fs.existsSync(file)) {
      fail(`package.json is missing: ${file}`);
    }
    let text;
    try {
      text = fs.readFileSync(file, 'utf8');
    } catch (e) {
      fail(`cannot read ${file}: ${e.message}`);
    }
    try {
      parsed.set(file, JSON.parse(text));
    } catch (e) {
      fail(`package.json contains invalid JSON (${file}): ${e.message}`);
    }
  }

  // ---- Phase 3: analyze React versions ----
  // Collect every react/react-dom spec across dependency sections.
  const specs = []; // { file, section, key, spec, version }
  for (const [file, pkg] of parsed.entries()) {
    for (const section of DEP_SECTIONS) {
      const deps = pkg[section];
      if (!deps || typeof deps !== 'object') continue;
      for (const key of REACT_KEYS) {
        if (deps[key] !== undefined) {
          const version = parseBaseVersion(deps[key]);
          specs.push({ file, section, key, spec: deps[key], version });
        }
      }
    }
  }

