    ok('No React dependencies found. No conflicts exist. No changes made.');
    process.exit(0);
  }

  // Any unparseable React spec means we cannot reason about compatibility.
  const unparseable = specs.filter((s) => s.version === null);
  if (unparseable.length > 0) {
    const details = unparseable.map((s) => `  ${s.file} [${s.section}] ${s.key}: "${s.spec}"`).join('\n');
