  }

  const majors = new Set(specs.map((s) => s.version.major));
  if (majors.size <= 1) {
    ok(`No React peer dependency conflicts detected (react major: ${[...majors][0]}). No changes made.`);
    process.exit(0);
  }

  // ---- Phase 4: resolve to the highest React version found ----
  let target = specs[0].version;
  for (const s of specs) {
    if (compareVersions(s.version, target) > 0) target = s.version;
  }

  // Sanity: target must be a real version.
  if (!target || !Number.isInteger(target.major)) {
    fail('Unresolvable React version conflicts: could not determine a compatible React version.');
  }

  const unifiedReactSpec = `^${target.base}`;
  const unifiedTypesSpec = `^${target.major}.0.0`;

  // Compute in-memory updates only; do not touch disk yet.
  const updates = []; // { file, section, key, from, to }
  for (const [file, pkg] of parsed.entries()) {
    for (const section of DEP_SECTIONS) {
      const deps = pkg[section];
      if (!deps || typeof deps !== 'object') continue;
      for (const key of REACT_KEYS) {
        if (deps[key] !== undefined && deps[key] !== unifiedReactSpec) {
          updates.push({ file, section, key, from: deps[key], to: unifiedReactSpec, pkg });
        }
      }
      for (const key of TYPES_KEYS) {
        if (deps[key] !== undefined) {
          const v = parseBaseVersion(deps[key]);
          if (v === null) {
            fail(`Unresolvable React version conflicts: unable to parse "${key}: ${deps[key]}" in ${file} [${section}].`);
          }
          if (v.major !== target.major) {
            updates.push({ file, section, key, from: deps[key], to: unifiedTypesSpec, pkg });
          }
        }
      }
    }
  }

  if (updates.length === 0) {
    // Majors differed but nothing to update (should not happen); treat as unresolvable.
    fail(`Unresolvable React version conflicts: detected majors ${[...majors].join(', ')} but no compatible update could be computed.`);
  }

  // ---- Phase 5: apply updates to disk ----
  const touched = new Set();
  try {
    for (const u of updates) {
      u.pkg[u.section][u.key] = u.to;
      touched.add(u.file);
    }
    for (const file of touched) {
      fs.writeFileSync(file, JSON.stringify(parsed.get(file), null, 2) + '\n', 'utf8');
    }
  } catch (e) {
    fail(`failed to update package.json files: ${e.message}`);
  }

  for (const u of updates) {
    ok(`Updated ${u.file} [${u.section}] ${u.key}: "${u.from}" -> "${u.to}"`);
  }

  // ---- Phase 6: verify with npm install ----
  try {
    execSync('npm install', { cwd: ROOT, stdio: 'inherit' });
  } catch (e) {
    fail('npm install failed after applying React version fixes. See output above.');
  }

  ok(`All React versions aligned to ${unifiedReactSpec}. npm install completed successfully.`);
  process.exit(0);
}

